<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, idemKey } from '../api'
import { useAuthStore } from '../stores/auth'
type Ledger={ledgerNo:string;bizNo:string;type:string;deltaAvailableCent:number;deltaFrozenCent:number;availableAfterCent:number;frozenAfterCent:number;remark:string;createdAt:string;instanceId?:number;instanceNo?:string}
type Page<T>={items:T[];total:number;page:number;size:number}
const auth=useAuthStore(),router=useRouter(),wallet=ref<any>({}),rows=ref<Ledger[]>([]),tenants=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),dialog=ref(false),submitting=ref(false)
const tenantId=ref<number|undefined>(auth.isAdmin?undefined:auth.user?.tenantId||undefined),query=reactive({type:'',bizNo:'',dates:[] as string[],page:1,size:20}),form=reactive({amountYuan:'1000.00',remark:'Demo 账户充值'})
const canRecharge=computed(()=>auth.can('billing:recharge')&&!auth.isAdmin||auth.isAdmin&&!!tenantId.value)
const params=()=>({tenantId:auth.isAdmin?tenantId.value:undefined,type:query.type||undefined,bizNo:query.bizNo||undefined,startTime:query.dates[0],endTime:query.dates[1],page:query.page,size:query.size})
const load=async()=>{if(auth.isAdmin&&!tenantId.value){wallet.value={};rows.value=[];total.value=0;return}loading.value=true;error.value='';try{const [balance,page]=await Promise.all([api.get('/wallet',{params:{tenantId:auth.isAdmin?tenantId.value:undefined}}),api.get<Page<Ledger>>('/billing/ledgers',{params:params()})]);wallet.value=balance;rows.value=page.items;total.value=page.total;query.page=page.page;query.size=page.size}catch(e:any){error.value=`${e.message||'加载失败'}${e.traceId?`（追踪 ID：${e.traceId}）`:''}`}finally{loading.value=false}}
const cents=()=>{const match=form.amountYuan.trim().match(/^(0|[1-9]\d*)(?:\.(\d{1,2}))?$/);if(!match)return null;const value=BigInt(match[1])*100n+BigInt((match[2]||'').padEnd(2,'0'));return value>0n&&value<=100000000n?Number(value):null}
const recharge=async()=>{const amountCent=cents();if(amountCent===null){ElMessage.error('请输入 0.01 至 1,000,000.00 元，最多两位小数');return}await ElMessageBox.confirm(`确认向当前账户充值 ¥${form.amountYuan} 吗？`, '确认充值',{type:'warning'});submitting.value=true;try{await api.post('/wallet/recharges',{tenantId:auth.isAdmin?tenantId.value:null,amountCent,remark:form.remark},{headers:{'Idempotency-Key':idemKey()}});dialog.value=false;ElMessage.success('充值成功');await load()}finally{submitting.value=false}}
const search=async()=>{query.page=1;await load()};const reset=async()=>{Object.assign(query,{type:'',bizNo:'',dates:[],page:1});await load()};const money=(v:number)=>`¥${((v||0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2})}`
const openInstance=(row:any)=>{if(row.instanceId)router.push({path:'/instances',query:{keyword:row.instanceNo||String(row.instanceId)}})}
onMounted(async()=>{if(auth.isAdmin){try{const page=await api.get<Page<any>>('/tenants',{params:{page:1,size:100}});tenants.value=page.items}catch(e:any){error.value=e.message||'租户加载失败'}}await load()})
</script>
<template><div class="billing"><div v-if="auth.isAdmin" class="panel tenant-picker"><b>结算租户</b><el-select v-model="tenantId" placeholder="请先选择租户" clearable @change="search"><el-option v-for="tenant in tenants" :key="tenant.id" :label="`${tenant.name}（${tenant.code}）`" :value="tenant.id"/></el-select></div><el-alert v-if="auth.isAdmin&&!tenantId" title="平台管理员请先选择租户，再查看钱包或充值。" type="info" :closable="false"/><template v-else><div class="grid stats" style="grid-template-columns:repeat(3,1fr)"><div class="panel stat"><div class="label">可用余额</div><div class="value success">{{money(wallet.availableCent)}}</div><div class="hint">可用于新订单冻结</div></div><div class="panel stat"><div class="label">冻结金额</div><div class="value">{{money(wallet.frozenCent)}}</div><div class="hint">等待引擎最终回调</div></div><div class="panel stat"><div class="label">账户总额</div><div class="value">{{money((wallet.availableCent||0)+(wallet.frozenCent||0))}}</div><el-button v-if="canRecharge" data-test="mutation" type="primary" link @click="dialog=true">账户充值 →</el-button></div></div><div class="panel"><div class="panel-title"><h3>不可变账务流水</h3><span class="muted">流水只追加，不支持编辑或删除</span></div><div class="filters"><el-select v-model="query.type" clearable placeholder="全部类型" @change="search"><el-option label="充值" value="RECHARGE"/><el-option label="冻结" value="FREEZE"/><el-option label="扣费" value="DEDUCT"/><el-option label="解冻" value="UNFREEZE"/></el-select><el-input v-model="query.bizNo" clearable placeholder="业务号 / 实例订单号" @change="search" @keyup.enter="search"/><el-date-picker v-model="query.dates" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" @change="search"/><el-button @click="search">搜索</el-button><el-button text @click="reset">重置</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"><template #default><el-button link @click="load">重试</el-button></template></el-alert><el-table v-loading="loading" :data="rows" empty-text="暂无符合条件的流水"><el-table-column prop="ledgerNo" label="流水号"/><el-table-column label="业务号"><template #default="s"><el-button v-if="s.row.instanceId" link type="primary" @click="openInstance(s.row)">{{s.row.bizNo}}</el-button><span v-else>{{s.row.bizNo}}</span></template></el-table-column><el-table-column prop="type" label="类型"/><el-table-column label="可用变动"><template #default="s"><span :class="s.row.deltaAvailableCent<0?'danger':'success'">{{money(s.row.deltaAvailableCent)}}</span></template></el-table-column><el-table-column label="冻结变动"><template #default="s">{{money(s.row.deltaFrozenCent)}}</template></el-table-column><el-table-column label="余额快照"><template #default="s">{{money(s.row.availableAfterCent)}} / {{money(s.row.frozenAfterCent)}}</template></el-table-column><el-table-column prop="createdAt" label="时间"/><el-table-column prop="remark" label="说明"/></el-table><div class="pager"><el-pagination v-model:current-page="query.page" v-model:page-size="query.size" background layout="total, sizes, prev, pager, next" :page-sizes="[20,50,100]" :total="total" @change="load"/></div></div></template><el-dialog v-model="dialog" title="钱包充值" width="430"><el-form label-width="92"><el-form-item label="金额（元）" required><el-input v-model="form.amountYuan" placeholder="例如 1000.00"/><div class="muted">将精确转换为分，不使用浮点计算。</div></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" maxlength="255"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button data-test="mutation" type="primary" :loading="submitting" @click="recharge">确认充值</el-button></template></el-dialog></div></template>
<style scoped>.tenant-picker{display:flex;align-items:center;gap:16px;margin-bottom:16px}.tenant-picker .el-select{width:320px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0 16px}.filters .el-select{width:120px}.filters .el-input{width:200px}.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
